package com.snaphere.api.social;
import com.snaphere.api.common.security.*; import com.snaphere.api.common.web.*; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/users") public class FollowController {private final FollowService service;private final CurrentUserProvider current;public FollowController(FollowService s,CurrentUserProvider c){service=s;current=c;} @PutMapping("/{userId}/follow") ResponseEntity<ApiResponse<SocialDtos.FollowResult>> follow(@PathVariable UUID userId,HttpServletRequest r){return ok(service.follow(current.require(r).userId(),userId),r);}@DeleteMapping("/{userId}/follow") ResponseEntity<ApiResponse<SocialDtos.FollowResult>> unfollow(@PathVariable UUID userId,HttpServletRequest r){return ok(service.unfollow(current.require(r).userId(),userId),r);}@GetMapping("/{userId}/followers") ResponseEntity<ApiResponse<CursorPage<SocialDtos.UserSummary>>> followers(@PathVariable UUID userId,@RequestParam(required=false)String cursor,@RequestParam(required=false)Integer size,HttpServletRequest r){return ok(service.followers(userId,cursor,size,current.optional(r).map(CurrentUser::userId)),r);}@GetMapping("/{userId}/following") ResponseEntity<ApiResponse<CursorPage<SocialDtos.UserSummary>>> following(@PathVariable UUID userId,@RequestParam(required=false)String cursor,@RequestParam(required=false)Integer size,HttpServletRequest r){return ok(service.following(userId,cursor,size,current.optional(r).map(CurrentUser::userId)),r);}@GetMapping("/recommendations") ResponseEntity<ApiResponse<List<SocialDtos.UserSummary>>> recommendations(@RequestParam(required=false)Integer limit,HttpServletRequest r){return ok(service.recommendations(current.require(r).userId(),limit),r);}private <T> ResponseEntity<ApiResponse<T>> ok(T body,HttpServletRequest r){return ResponseEntity.ok(ApiResponse.ok(body,TraceIdFilter.currentTraceId(r)));}}
